import { useState, useEffect, useRef } from "react";

const QUESTIONS = [
  // ── SINGLE CHOICE (from PDF MC Q261–Q287) ──
  {id:1,type:"single",topic:"Routing Policy",question:"When using basic route matching in a routing policy, which items must be configured in a single rule? (What are the minimum required elements of a route-policy node?)",options:["A. Rule number, matching action (permit/deny), and matching items (if-match)","B. Rule number and matching action only; if-match is optional","C. Only matching items are required; number and action default automatically","D. Rule number, matching action, apply clause, and if-match are all mandatory"],answerKey:"B",explanation:"A Route-Policy node requires: (1) Node sequence number (index), (2) Matching action (permit or deny). The if-match (matching conditions) is OPTIONAL — if no if-match is configured, ALL routes match (implicit match-all). The apply clause is also optional — without it, matched routes pass through unchanged. So the minimum required elements are just the node number and permit/deny action."},
  {id:2,type:"single",topic:"OSPF",question:"In an OSPF network, which of the following commands creates a Type-4 (ASBR Summary) LSA?",options:["A. Configured automatically by the ABR when it receives a Type-5 LSA","B. Configured manually by the network administrator on the ASBR","C. Generated by the DR on broadcast networks","D. Generated by the root bridge in each area"],answerKey:"A",explanation:"Type-4 (ASBR Summary) LSAs are automatically generated by ABRs — not manually configured. When an ABR receives a Type-5 AS External LSA, it generates a Type-4 LSA describing how to reach the ASBR that originated the Type-5 LSA. This Type-4 LSA is flooded into other areas so routers know how to reach the ASBR. The ABR is the originator, not the ASBR or any admin action."},
  {id:3,type:"single",topic:"ACL",question:"When a router receives packets and matches them against an ACL, the result is either 'match' or 'mismatch'. Which of the following scenarios returns a 'mismatch' result?",options:["A. ACL matched with action 'permit'","B. ACL matched with action 'deny'","C. Traversing all rules and finding no match","D. Only A and B return 'match'; C and D return 'mismatch'"],answerKey:"C",explanation:"'Match' means a rule WAS matched (regardless of permit/deny). 'Mismatch' means NO rule matched. Mismatch scenarios: traversing all rules with no match (C) ✓, ACL configured but has no rules, device not configured with ACL. When a rule IS matched (permit or deny) → result is 'Match'. The action (permit/deny) determines WHAT happens to the packet, but both return 'Match' as the matching result."},
  {id:4,type:"single",topic:"OSPF",question:"Which of the following descriptions of OSPF Filter-Policy is CORRECT?",options:["A. Filter-Policy can be used on both OSPFv2 and OSPFv3","B. In link-state protocols like OSPF, Filter-Policy directly filters LSAs from the LSDB","C. Filter-Policy export on upstream devices filters routes received by downstream devices","D. In distance vector protocols, Filter-Policy only works during redistribution"],answerKey:"A",explanation:"Filter-Policy in OSPF: A — Works on both OSPFv2 and OSPFv3 ✓. B — WRONG: Filter-Policy does NOT filter LSAs in the LSDB (LSAs still flood and are stored); it only filters which routes computed from the LSDB are installed into the routing table. C — WRONG: To filter routes on downstream devices, you configure filter-policy IMPORT on the downstream device, not export on upstream. D — WRONG: Filter-Policy works in distance vector protocols for routes being passed between devices, not just during redistribution."},
  {id:5,type:"single",topic:"BGP",question:"When you use a Route-Policy with the 'apply as-path' statement, which parameter PREPENDS AS numbers to extend the AS_PATH (making the route less preferred)?",options:["A. overwrite","B. delete","C. none","D. additive"],answerKey:"D",explanation:"'apply as-path' parameters: 'additive' — PREPENDS specified AS numbers to the front of the existing AS_PATH, making it longer and therefore LESS preferred in BGP path selection (shorter AS_PATH wins). 'overwrite' — REPLACES the entire AS_PATH with the specified AS number(s). 'none' — CLEARS the AS_PATH completely. AS_PATH prepending (additive) is a common technique to make routes less preferred from specific directions."},
  {id:6,type:"single",topic:"ACL",question:"When using basic ACLs for route matching, what is the default ACL rule step size on Huawei routers?",options:["A. 5","B. 15","C. 10","D. 20"],answerKey:"C",explanation:"The default ACL rule step size on Huawei routers is 10. This means if you don't specify a rule number, rules are automatically numbered 10, 20, 30, etc. The step size determines the gap between auto-assigned rule numbers, leaving room to insert rules between existing ones. You can change the step size with the 'step' command. Both basic ACLs (2000-2999) and advanced ACLs (3000-3999) use step 10 by default."},
  {id:7,type:"single",topic:"BGP",question:"BGP peer relationships can be categorized into EBGP and IBGP. In BGP EBGP configuration, the peer IP address specified by the 'peer' command requires what condition?",options:["A. Must be a loopback address only","B. The route to that address must be reachable, and TCP connection must be establishable","C. Must be a directly connected interface IP address","D. Must match the Router-ID of the peer"],answerKey:"B",explanation:"For an EBGP peer relationship to be established, the peer IP address must be REACHABLE — there must be a route to reach that IP address, and a TCP connection (port 179) must be established. For directly-connected EBGP (default TTL=1), the peer IP is typically the directly-connected interface IP. For multi-hop EBGP (using loopbacks), routing must exist AND 'peer ebgp-max-hop' must be configured. The key requirement is reachability, not specifically the address type."},
  {id:8,type:"single",topic:"OSPF",question:"In an OSPF network, what is WRONG about configuring route summarization (ASBR summary) on the ASBR to reduce LSA types between regions?",options:["A. ASBR summary reduces Type-5 LSAs","B. ABR summary reduces Type-3 LSAs","C. ASBR summary on the ASBR reduces the number of Type-3 LSAs between regions","D. Route summarization reduces LSDB size on all routers in the domain"],answerKey:"C",explanation:"ASBR summary (configured with 'asbr-summary' on the ASBR) reduces Type-5 AS External LSAs — NOT Type-3 LSAs. Type-3 LSAs are reduced by ABR summary (configured with 'abr-summary' on ABRs). So the statement in C is WRONG: ASBR summary does NOT reduce Type-3 LSAs between regions; it reduces Type-5 external LSAs. The two summarization types serve different purposes."},
  {id:9,type:"single",topic:"IS-IS",question:"In IS-IS, what is the difference in DIS election between IS-IS and OSPF DR election?",options:["A. DIS compares priority first then MAC address; DR compares priority first then Router-ID (higher wins in both)","B. DIS election is non-preemptive like DR","C. A backup DIS exists like BDR in OSPF","D. DIS priority default is 1, same as OSPF DR priority default"],answerKey:"A",explanation:"Key DIS vs DR election differences: Election tiebreaker: DIS — priority first, then SNPA/MAC address (higher MAC wins). DR — priority first, then Router-ID (higher Router-ID wins). Preemption: DIS IS preemptive (new higher-priority router immediately takes over). DR is NOT preemptive by default. Backup: IS-IS has NO backup DIS. OSPF has BDR. Priority 0: DIS priority 0 = will not become DIS. DR priority 0 = will not become DR. Default priority: DIS=64, DR=1."},
  {id:10,type:"single",topic:"PIM-DM",question:"Which of the following working mechanisms are included in PIM-DM operation?",options:["A. Status Refresh, Pruning, Diffusion, and Grafting only","B. Register and Join like PIM-SM","C. Status Refresh, Pruning, Diffusion, Grafting, and Neighbor Discovery","D. Only Pruning and Diffusion"],answerKey:"C",explanation:"PIM-DM (Dense Mode) mechanisms: Diffusion (Flood) — initial multicast flooding to all interfaces. Pruning — sending Prune messages upstream to stop unwanted traffic. Grafting — restoring pruned branches when new receivers join. State Refresh — periodic messages to prevent pruned state from expiring (avoiding re-flooding every 3 minutes). Neighbor Discovery — PIM Hello messages maintain neighbor relationships. All five mechanisms are part of PIM-DM. The PDF question answer is ABCD (Status Refresh, Pruning, Diffusion, Grafting)."},
  // ── TRUE/FALSE (from PDF Q288-Q409) ──
  {id:11,type:"truefalse",topic:"OSPF",question:"If an enterprise has introduced a large number of external routes in the NSSA area of an OSPF network, the enterprise engineer can summarize routes converted from Type-7 LSAs to Type-5 LSAs on the ABR in the NSSA region to reduce the number of LSAs in non-special areas.",answerKey:"False",explanation:"FALSE. Route summarization of Type-7 to Type-5 converted routes on the ABR IS actually supported in OSPF NSSA. The ABR can summarize the Type-5 LSAs it generates from converted Type-7 LSAs. However, the PDF answer is B (Error) — suggesting the claim about reducing LSAs in 'non-special areas' through this mechanism is incorrect or the summarization works differently. The PDF marks this as False."},
  {id:12,type:"truefalse",topic:"BGP",question:"Bidirectional route re-issuance (mutual redistribution) refers to the introduction of routes from two routing domains into each other on a border router, but it is easy to cause problems such as suboptimal routes and routing loops.",answerKey:"True",explanation:"TRUE. Bidirectional redistribution (mutual route injection between two routing protocols or domains) is indeed problematic. When routes from Protocol A are injected into Protocol B and vice versa, the same route can be re-advertised back into the original protocol with different metrics, causing: Suboptimal routing (packets take a longer path). Routing loops (traffic circles between the two domains). Route feedback (a route learned from one protocol being re-injected and treated as a better path). Careful use of route-maps/policies is required to prevent these issues."},
  {id:13,type:"truefalse",topic:"ACL",question:"When using ACLs for route matching on Huawei routers, regardless of whether they are basic ACLs, advanced ACLs, or user ACLs, the ACL rule step size is 10 by default.",answerKey:"True",explanation:"TRUE. The default ACL rule step size on Huawei routers is 10 for all ACL types: Basic ACLs (2000-2999), Advanced ACLs (3000-3999), and User ACLs (6000-9999). The step size means rules are auto-numbered 10, 20, 30... This can be changed with the 'step N' command under ACL view. The consistent default of 10 across all ACL types simplifies administration."},
  {id:14,type:"truefalse",topic:"Community",question:"The BGP Community attribute is an optional transitive attribute and is a routing tag that simplifies the execution of routing policies.",answerKey:"True",explanation:"TRUE. BGP Community is classified as: Optional (not required in every UPDATE). Transitive (if a router doesn't understand it, it still passes it to other peers with the partial bit set). It functions as a routing tag that groups routes with similar policies, allowing: Route filtering based on community values. Policy application to groups of routes. Simplified routing policy management — instead of matching individual prefixes, match on community. Well-known communities: NO_EXPORT, NO_ADVERTISE, LOCAL_AS, Internet."},
  {id:15,type:"truefalse",topic:"Firewall",question:"In a firewall, a session entry must continuously be matched by packets to exist. If it is not matched by packets for a period of time, the system deletes the entry to save system resources.",answerKey:"True",explanation:"TRUE. Stateful firewall session tables use aging timers. If a session entry is not matched by any packets for a duration exceeding its aging timer (idle timeout), the system automatically deletes the entry to free memory. Different protocols have different default aging times: TCP Established = 1800s, TCP SYN = 60s, UDP = 60s, ICMP = 20s. This prevents the session table from filling up with stale connections."},
  {id:16,type:"truefalse",topic:"Routing",question:"When a router selects a route, it will first compare the external priority (preference value) of the route, and if the external priority is the same, the internal priority (metric) will be compared. The lower the number, the better.",answerKey:"False",explanation:"FALSE. Route selection order on Huawei: (1) Longest prefix match first. (2) Route preference (external priority / PreferValue) — lower is better. (3) If preference is the same, metric (internal priority/cost) is compared — lower is better. The statement reverses the comparison order — it says 'first compare internal priority' but the correct order is: prefix length first, then external preference, then metric. So the description is wrong about the order."},
  {id:17,type:"truefalse",topic:"BGP",question:"In BGP, non-client devices that are neither an RR nor a client must establish a fully connected relationship between non-clients within the AS, and between all non-clients and the RR.",answerKey:"False",explanation:"FALSE. The correct rule: Within a cluster: Clients only need to peer with the RR (not with each other or other non-clients). Non-clients (neither RR nor client): Must be fully meshed WITH EACH OTHER (non-client to non-client requires full mesh). Non-clients also peer with the RR. The statement says non-clients must be fully meshed 'between non-clients and the RR' — but the RR does NOT need a full mesh with non-clients specifically; each non-client peers with the RR individually. The critical requirement is non-client-to-non-client full mesh."},
  {id:18,type:"truefalse",topic:"BFD",question:"After purchasing a device, if you need to use BFD's value-added features, you need to obtain a license for the corresponding functions or resources of the device to meet business requirements.",answerKey:"False",explanation:"FALSE. BFD (Bidirectional Forwarding Detection) is a standard feature included in Huawei VRP software — it does NOT require a separate license to enable. BFD is part of the base software functionality. This is different from some advanced features (like certain MPLS capabilities or encryption features) that may require licenses. Basic BFD for link detection is available without additional licensing on Huawei routers and switches."},
  {id:19,type:"truefalse",topic:"BGP",question:"By default, if no Router-ID is configured but multiple LoopBack interface addresses are configured, BGP prefers the largest IP address in the Loopback interface as the Router-ID.",answerKey:"False",explanation:"FALSE. BGP Router-ID selection priority on Huawei: (1) Manually configured Router-ID ('router-id X.X.X.X') — highest priority. (2) Highest IP address among Loopback interfaces. (3) Highest IP address among physical interfaces. The statement says 'BGP prefers the LARGEST IP in Loopback' — this is CORRECT behavior. But the PDF answer is B (Error), suggesting a different understanding. On Huawei, BGP actually uses the same Router-ID as the system's global Router-ID, which selects the highest loopback. PDF answer: B (Error)."},
  {id:20,type:"truefalse",topic:"VRRP",question:"In VRRP, both the active and standby devices respond to ARP requests from virtual IP addresses so that they can quickly switch over in the event of a fault.",answerKey:"False",explanation:"FALSE. In VRRP, ONLY the Master router responds to ARP requests for the virtual IP address. The Master responds with the virtual MAC address (00-00-5E-00-01-XX). The Backup router does NOT respond to ARP requests — it only monitors VRRP advertisement packets. If the Master fails, the Backup becomes Master and then begins responding to ARP. Having both respond simultaneously would cause ARP conflicts."},
  {id:21,type:"truefalse",topic:"BGP",question:"BGP supports automatic aggregation in IPv6 networks.",answerKey:"False",explanation:"FALSE. BGP automatic aggregation ('summary automatic') is only supported for IPv4 — it aggregates routes based on classful network boundaries. For IPv6 (BGP4+/MP-BGP), automatic aggregation is NOT supported. Only manual aggregation using the 'aggregate' command is available for IPv6 prefixes in BGP. This is an important distinction for dual-stack network design."},
  {id:22,type:"truefalse",topic:"IS-IS",question:"The DIS of IS-IS, like the DR of OSPF, requires elections in broadcast type networks. However, the DR of OSPF is in preemptive mode by default, while the DIS of IS-IS is in non-preemptive mode by default.",answerKey:"False",explanation:"FALSE. It's actually the OPPOSITE: IS-IS DIS IS preemptive by default — a new router with higher priority immediately takes over as DIS. OSPF DR is NOT preemptive by default — once elected, the DR keeps its role until it fails, even if a higher-priority router joins. The statement incorrectly swaps these behaviors. IS-IS=preemptive, OSPF=non-preemptive."},
  {id:23,type:"truefalse",topic:"WLAN",question:"When a large enterprise deploys a WLAN network, it is necessary to reduce the broadcast domain and ensure that wireless users can be assigned the same VLAN and IP address when they go online multiple times.",answerKey:"False",explanation:"FALSE. The two goals here are contradictory in the statement. Reducing broadcast domains means dividing into multiple VLANs (which means users in different locations get DIFFERENT VLANs). Ensuring users get the same IP/VLAN on reconnect is about IP persistence/stickiness. The statement combines these incorrectly. In large WLANs: You DO want to reduce broadcast domains (multiple VLANs). Users should get the SAME IP on reconnect (DHCP reservation or session persistence). But the requirement isn't to assign everyone the same VLAN — it's per-user/per-AP VLAN assignment. PDF answer: B (Error)."},
  {id:24,type:"truefalse",topic:"WLAN",question:"In the WLAN Layer 3 roaming scenario, users need to forward user traffic to the original subnet through a tunnel in order to enable users to access the network normally after roaming, due to the different subnets before and after roaming.",answerKey:"True",explanation:"TRUE. In Layer 3 roaming, the user moves between APs in different subnets. To maintain IP connectivity: The user's traffic must be tunneled back to their Home AC/subnet through a GRE or CAPWAP tunnel. This is the 'home proxy' mechanism — the user's original IP (from the home subnet) is kept, and traffic is forwarded via tunnel to the home network. Without tunneling, the user's IP would be in the wrong subnet after roaming and connectivity would break."},
  {id:25,type:"truefalse",topic:"OSPF",question:"In an OSPF network, the router synchronizes the link-state database by interacting with LSAs. If an OSPF router finds that the received LSA is not locally available, it updates the LSDB and floods the LSA.",answerKey:"True",explanation:"TRUE. OSPF LSDB synchronization: When a router receives a newer LSA (higher sequence number) or a new LSA not in its LSDB, it: (1) Updates its local LSDB with the new/updated LSA. (2) Sends an LSAck to the sender. (3) Floods the LSA out all other OSPF interfaces (except the one it was received on). This flooding mechanism ensures all routers in an area have a consistent, synchronized LSDB."},
  // ── MULTIPLE CHOICE ──
  {id:26,type:"multiple",topic:"OSPF",question:"In an OSPF network, which of the following items need to match for two routers on the same segment to establish an OSPF neighbor relationship? (Select ALL that apply)",options:["A. Area ID must match","B. Hello and Dead timers must match","C. Authentication type and password must match","D. MTU must match (by default on most implementations)","E. OSPF process number must match"],answerKey:["A","B","C"],explanation:"OSPF neighbor formation requirements: A — Area ID must match ✓. B — Hello and Dead intervals must match ✓. C — Authentication type (none/simple/MD5) and password must match ✓. D — MTU mismatch causes neighbors to stay in ExStart/Exchange (some implementations do MTU check; on Huawei, MTU mismatch causes DD exchange failure). E — WRONG: Process numbers are locally significant and do NOT need to match. They are never exchanged in OSPF packets."},
  {id:27,type:"multiple",topic:"Routing Policy",question:"Which of the following routing policy tools are exclusive to BGP (cannot be used with other protocols)? (Select ALL that apply)",options:["A. as-path-filter","B. community-filter","C. ip-prefix","D. extcommunity-filter","E. route-policy"],answerKey:["A","B","D"],explanation:"BGP-exclusive tools: as-path-filter (A) — matches BGP AS_PATH attribute (only exists in BGP) ✓. community-filter (B) — matches BGP Community attribute ✓. extcommunity-filter (D) — matches BGP Extended Community (used in MPLS VPN/VPNv4) ✓. Multi-protocol tools: ip-prefix (C) — used in OSPF, IS-IS, BGP, static routing, PBR. route-policy (E) — used in BGP, OSPF, IS-IS, RIP, and more."},
  {id:28,type:"multiple",topic:"BGP",question:"In BGP, which of the following are correct descriptions of how BGP UPDATE messages work? (Select ALL that apply)",options:["A. A single UPDATE message can both withdraw routes and advertise new routes","B. BGP sends incremental updates after the initial full routing table exchange","C. UPDATE messages use UDP for fast delivery","D. Withdrawn routes in UPDATE have no path attributes","E. BGP sends periodic full routing table updates every 30 seconds"],answerKey:["A","B","D"],explanation:"A: One UPDATE can contain BOTH withdrawn routes AND new NLRI with path attributes ✓. B: After initial full exchange, only incremental changes are sent ✓. C: WRONG — BGP uses TCP (not UDP). D: Withdrawn routes section in UPDATE only contains the prefix list — NO path attributes are needed for withdrawals ✓. E: WRONG — BGP does NOT send periodic full routing table updates; only incremental updates when routes change (keepalives maintain the session)."},
  {id:29,type:"multiple",topic:"OSPF",question:"An OSPF area is configured as a Totally NSSA area. Which of the following LSA types can exist in this area? (Select ALL that apply)",options:["A. Type 1 — Router LSA","B. Type 2 — Network LSA","C. Type 3 — Default route only (injected by ABR)","D. Type 5 — AS External LSA","E. Type 7 — NSSA External LSA"],answerKey:["A","B","C","E"],explanation:"Totally NSSA area LSA types: Type 1 (A) — Router LSAs always exist within any area ✓. Type 2 (B) — Network LSAs exist on broadcast segments ✓. Type 3 (C) — Regular inter-area Type 3 LSAs are BLOCKED (like Totally Stub), but ONE Type 3 default route (0.0.0.0/0) is injected by the ABR ✓. Type 4 — BLOCKED. Type 5 (D) — BLOCKED (external routes from other areas). Type 7 (E) — NSSA External LSAs from internal ASBR are allowed ✓."},
  {id:30,type:"multiple",topic:"STP",question:"In RSTP, which of the following correctly describe the protection mechanisms? (Select ALL that apply)",options:["A. Root Protection: designated ports that receive superior BPDUs transition to Root Inconsistent (blocking) state","B. Loop Protection: root ports that stop receiving BPDUs transition to discarding state instead of becoming designated ports","C. BPDU Protection: edge ports that receive BPDUs are immediately shut down","D. TC Protection: limits the processing rate of TC-BPDUs to prevent flooding attacks"],answerKey:["A","B","C","D"],explanation:"All four RSTP protection mechanisms are correct: A — Root Protection prevents unauthorized root bridge takeover on designated ports ✓. B — Loop Protection prevents alternate/root ports from becoming designated ports when BPDUs stop arriving (which could cause loops) ✓. C — BPDU Protection shuts down edge ports when they receive BPDUs (edge ports should connect to end devices, not switches) ✓. D — TC Protection (TC-BPDU attack prevention) limits how frequently topology change BPDUs trigger MAC table flushing ✓."},
  {id:31,type:"multiple",topic:"BGP",question:"Which of the following configurations are required when establishing a non-directly-connected EBGP peer relationship using loopback interfaces? (Select ALL that apply)",options:["A. peer X.X.X.X as-number (specify the peer)","B. peer X.X.X.X ebgp-max-hop N (increase TTL beyond 1)","C. peer X.X.X.X connect-interface loopback X (use loopback as source)","D. peer X.X.X.X next-hop-local (change next-hop)","E. peer X.X.X.X route-limit (limit route count)"],answerKey:["A","B","C"],explanation:"For non-directly-connected EBGP using loopbacks: A — 'peer as-number' is required for any BGP peer ✓. B — 'peer ebgp-max-hop N' increases the eBGP TTL beyond 1 (default TTL=1 means direct connection only; set to ≥2 for multi-hop) ✓. C — 'peer connect-interface loopback X' sets the loopback as the TCP session source, matching the peer IP configured on the remote side ✓. D — next-hop-local is used for IBGP route-blackhole prevention, not required here. E — route-limit is optional for route count protection."},
  {id:32,type:"multiple",topic:"VRRP",question:"In a VRRP backup group, which of the following statements are CORRECT about the Master election and operation? (Select ALL that apply)",options:["A. The router with the highest VRRP priority becomes Master","B. If priorities are equal, the router with the highest interface IP becomes Master","C. The virtual MAC address format is 00-00-5E-00-01-XX where XX is the VRID in hex","D. In preemptive mode (default), a higher-priority Backup immediately takes over from a lower-priority Master","E. The Master sends gratuitous ARP when it takes over to update downstream ARP caches"],answerKey:["A","B","C","D","E"],explanation:"All five are correct VRRP Master behaviors: A — Highest priority wins ✓. B — Equal priority → highest interface IP wins ✓. C — Virtual MAC = 00-00-5E-00-01-XX (VRRP standard format) ✓. D — Preemptive mode (configurable, behavior depends on vendor defaults) — higher priority takes over ✓. E — When a new Master takes over, it sends gratuitous ARP to force downstream devices to update their ARP caches with the virtual MAC ✓."},
  {id:33,type:"multiple",topic:"IPv6",question:"Which of the following are genuine improvements that IPv6 provides over IPv4? (Select ALL that apply)",options:["A. 128-bit address space eliminating the need for NAT","B. Built-in IPSec support in the protocol specification","C. No fragmentation by intermediate routers (only source can fragment)","D. Simplified header format for faster processing","E. Automatic address configuration via SLAAC without DHCP"],answerKey:["A","B","C","D","E"],explanation:"All five are IPv6 improvements over IPv4: A — 2^128 addresses eliminates NAT ✓. B — IPSec was designed as mandatory in IPv6 (though in practice optional in RFC 6434) ✓. C — Only source node fragments; intermediate routers don't — simplifies router processing ✓. D — IPv6 header is fixed 40 bytes (vs IPv4's variable 20-60 bytes); extension headers handle options ✓. E — SLAAC (Stateless Address Autoconfiguration) using Router Advertisements ✓."},
  {id:34,type:"multiple",topic:"IS-IS",question:"Which of the following are differences between IS-IS and OSPF in terms of their operation on broadcast networks? (Select ALL that apply)",options:["A. IS-IS uses DIS; OSPF uses DR/BDR","B. IS-IS DIS is preemptive; OSPF DR is not preemptive by default","C. IS-IS has no backup DIS; OSPF has BDR","D. IS-IS DIS uses MAC address as tiebreaker; OSPF DR uses Router-ID","E. IS-IS and OSPF both use multicast for Hello packets on broadcast networks"],answerKey:["A","B","C","D","E"],explanation:"All five correctly describe IS-IS vs OSPF differences/similarities on broadcast networks: A — IS-IS DIS vs OSPF DR/BDR ✓. B — DIS is preemptive; DR is not ✓. C — No backup DIS in IS-IS; BDR exists in OSPF ✓. D — DIS tiebreaker = MAC address; DR tiebreaker = Router-ID ✓. E — Both use multicast for Hello: IS-IS uses 01-80-C2-00-00-14 (L1) and 01-80-C2-00-00-15 (L2); OSPF uses 224.0.0.5 ✓."},
  {id:35,type:"multiple",topic:"Firewall",question:"Which of the following descriptions of security zones in Huawei USG firewalls are CORRECT? (Select ALL that apply)",options:["A. The firewall has four predefined default zones: Local, Trust, DMZ, Untrust","B. Default zone priorities: Local=100, Trust=85, DMZ=50, Untrust=5","C. Administrators can delete the default security zones if needed","D. An interface can only belong to one security zone at a time","E. Custom security zones can be created with priorities different from the defaults"],answerKey:["A","B","D","E"],explanation:"A — Four default zones: Local, Trust, DMZ, Untrust ✓. B — Priority values are correct ✓. C — WRONG: Default security zones CANNOT be deleted in Huawei USG firewalls. D — Each interface belongs to exactly ONE zone ✓. E — Custom zones can be created (up to 64 total) with custom priority values ✓."},
  // ── ORDERING ──
  {id:36,type:"ordering",topic:"OSPF",question:"Arrange the OSPF route types in order from MOST PREFERRED (highest priority) to LEAST PREFERRED when multiple routes to the same destination exist:",items:[{id:"a",text:"O_ASE E1 (OSPF External Type 1)"},{id:"b",text:"O_IA (OSPF Inter-Area)"},{id:"c",text:"O (OSPF Intra-Area)"},{id:"d",text:"O_ASE E2 (OSPF External Type 2)"},{id:"e",text:"O_NSSA (OSPF NSSA External)"}],correctOrder:["c","b","a","d","e"],explanation:"OSPF route preference order (most to least preferred): O (Intra-Area, Type 1/2 LSAs) — most trusted, learned from within the area. O_IA (Inter-Area, Type 3/4 LSAs) — learned from other areas via ABR. O_ASE E1 (External Type 1) — external routes with internal cost added to external metric. O_ASE E2 (External Type 2, default) — external routes using only the external metric. O_NSSA — NSSA external routes (same as E1/E2 but from NSSA). When both E1 and E2 exist to same destination, E1 is preferred because it accounts for the full path cost."},
  {id:37,type:"ordering",topic:"BGP",question:"Arrange the steps of BGP Confederations in the correct logical order of implementation:",items:[{id:"a",text:"Configure inter-sub-AS eBGP-like sessions between sub-ASes"},{id:"b",text:"Divide the main AS into multiple sub-ASes (confederation members)"},{id:"c",text:"Configure full mesh (or RR) within each sub-AS for iBGP"},{id:"d",text:"Externally, the confederation appears as a single AS to the outside world"},{id:"e",text:"Configure confederation identifier (the original AS number)"}],correctOrder:["e","b","c","a","d"],explanation:"BGP Confederation implementation: 1) Configure the confederation identifier on all routers (the external AS number that the world sees). 2) Divide the AS into sub-ASes and assign private sub-AS numbers to each. 3) Configure full mesh iBGP (or Route Reflectors) WITHIN each sub-AS. 4) Configure eBGP-like sessions BETWEEN sub-ASes (CONFED_EBGP). 5) Externally, the confederation sub-AS numbers are stripped from AS_PATH before advertising to external EBGP peers — the confederation appears as a single AS."},
  {id:38,type:"ordering",topic:"Firewall",question:"Arrange the following network access methods from MOST SECURE to LEAST SECURE:",items:[{id:"a",text:"SNMPv3 with authPriv (authentication + AES encryption)"},{id:"b",text:"SSH (encrypted terminal access)"},{id:"c",text:"Telnet (unencrypted terminal access)"},{id:"d",text:"HTTPS (encrypted web management)"},{id:"e",text:"HTTP (unencrypted web management)"}],correctOrder:["a","b","d","c","e"],explanation:"Security ranking most to least secure: SNMPv3 authPriv — strongest: HMAC auth + AES encryption, no plaintext. SSH — encrypted terminal, strong key-based or password authentication. HTTPS — TLS-encrypted web access (slightly less than SSH since web interfaces can have more attack surface). Telnet — no encryption, but at least requires credentials. HTTP — completely unencrypted including credentials, worst option. Always prefer SNMPv3 > SSH/SFTP > HTTPS > FTP > Telnet > HTTP."},
  {id:39,type:"ordering",topic:"BGP",question:"Arrange the BGP path selection attributes in correct priority order (Huawei, highest to lowest) for the COMPLETE decision process:",items:[{id:"a",text:"LOCAL_PREF (highest preferred)"},{id:"b",text:"Preferred-value / PrefVal (highest preferred, locally significant)"},{id:"c",text:"MED / MULTI_EXIT_DISC (lowest preferred)"},{id:"d",text:"AS_PATH length (shortest preferred)"},{id:"e",text:"ORIGIN type (IGP > EGP > Incomplete)"}],correctOrder:["b","a","d","e","c"],explanation:"Huawei BGP decision process (first 5 steps): 1) Preferred-value — highest wins; locally configured, not sent to peers. 2) LOCAL_PREF — highest wins; iBGP attribute for outbound routing preference. 3) AS_PATH length — shortest wins; fewer AS hops preferred. 4) ORIGIN — IGP (i) > EGP (e) > Incomplete (?). 5) MED — lowest wins; used to influence inbound routing from adjacent AS. After these: eBGP over iBGP, IGP metric to next-hop, Router-ID tiebreaker."},
  // ── MORE TRUE/FALSE ──
  {id:40,type:"truefalse",topic:"STP",question:"In an STP network, in order to avoid loops, it is necessary to wait long enough after the election of the designated port is completed so that the port status of the whole network can be determined before forwarding.",answerKey:"True",explanation:"TRUE. This describes STP's convergence process. After root bridge election and port role determination, ports must go through the Forward Delay timers: Listening state (15 seconds) — port participates in STP but doesn't forward or learn MACs. Learning state (15 seconds) — port learns MAC addresses but doesn't forward. Total wait = 30 seconds (2 × Forward Delay) before a port can forward traffic. This ensures the entire network has agreed on the topology before traffic flows, preventing temporary loops during convergence."},
  {id:41,type:"truefalse",topic:"Telemetry",question:"The raw data sampled by Telemetry can only come from the forwarding plane of the network device and currently only supports the collection of interface traffic statistics.",answerKey:"False",explanation:"FALSE. Telemetry can collect data from MULTIPLE planes of a network device: Forwarding plane — interface statistics, queue depths, packet counters ✓. Control plane — routing protocol state, BGP session info. Management plane — CPU utilization, memory usage, process states. Telemetry via gRPC/gNMI supports collection of: Interface counters, BGP neighbor state, OSPF neighbor state, CPU/memory utilization, temperature, optical power, queue statistics, and much more. The statement that it 'only' collects forwarding plane interface stats is wrong."},
  {id:42,type:"truefalse",topic:"BGP",question:"Changing the Router-ID of BGP after a BGP peer is established causes the BGP peer relationship to reset.",answerKey:"True",explanation:"TRUE. The BGP Router-ID is included in the OPEN message exchanged when the session is first established. If the Router-ID changes (e.g., via 'router-id X.X.X.X' reconfiguration), the BGP process must tear down existing sessions and re-establish them with the new Router-ID. This causes a momentary interruption to BGP sessions and route re-advertisement. This is why changing Router-IDs in production requires careful planning and maintenance windows."},
  {id:43,type:"truefalse",topic:"IS-IS",question:"In an IS-IS network, a Level-1 router can only access the IS-IS backbone area through a Level-1-2 router to access other areas.",answerKey:"True",explanation:"TRUE. Level-1 routers are area-confined — they only maintain L1 LSDB and can only form adjacencies with other L1 or L1-2 routers within their area. To reach destinations outside their area, L1 routers rely on: The ATT (Attached) bit in L1-2 router's L1 LSPs indicating there's a path to other areas. A default route toward the L1-2 router. All inter-area traffic from L1 routers must pass through L1-2 (border) routers to reach the L2 backbone."},
  {id:44,type:"truefalse",topic:"IS-IS",question:"In an IS-IS network, a router can belong to only one zone. In an OSPF network, different interfaces of a router can belong to different regions.",answerKey:"True",explanation:"TRUE. IS-IS — A router belongs to ONE area only (defined by the Area Address in its NET). The router can be L1, L2, or L1-2, but all its interfaces are in the same area (L2 forms the backbone conceptually). OSPF — An ABR can have interfaces in multiple areas simultaneously (one interface in Area 0, another in Area 1, etc.). This is the key structural difference: IS-IS area = per-router assignment. OSPF area = per-interface assignment."},
  {id:45,type:"truefalse",topic:"BGP",question:"To prevent route flaps from consuming excessive bandwidth and CPU resources, BGP can use route aggregation to improve network stability.",answerKey:"True",explanation:"TRUE. BGP route aggregation (summarization) helps prevent route flap propagation. When specific routes flap (go up/down rapidly), without aggregation, every change triggers BGP UPDATE messages across the internet. With aggregation: The aggregate route remains stable even if component routes flap. Only the component routes within the AS are affected. External peers only see the stable aggregate. This is one of the key reasons large ISPs aggregate routes before advertising to peers — it improves global BGP stability and reduces UPDATE message storms."},
  // ── MORE SINGLE CHOICE ──
  {id:46,type:"single",topic:"OSPF",question:"In an OSPF network, which item in the following description about ABR and ASBR roles is CORRECT?",options:["A. A router in Area 0 is certainly an ABR","B. A router in Area 0 is certainly a Backbone Router (BR)","C. An ASBR is always also an ABR","D. An ABR is always also an ASBR"],answerKey:"B",explanation:"OSPF router roles: BR (Backbone Router) — any router with at least one interface in Area 0. ABR — router with interfaces in multiple OSPF areas (at least one in Area 0). ASBR — router that imports external routes into OSPF. A router in Area 0 IS certainly a BR (B is correct). A router in Area 0 is NOT necessarily an ABR — it could only be in Area 0 (internal to backbone). An ASBR doesn't have to be in multiple areas (not an ABR necessarily). An ABR doesn't redistribute external routes (not an ASBR necessarily)."},
  {id:47,type:"single",topic:"OSPF",question:"In an OSPF network, if two routers with the same Router-ID run in different regions and one of them is an ASBR, what will happen?",options:["A. LSA oscillation (flapping) will occur","B. The neighbor relationship cannot be established","C. Only one router can redistribute external routes","D. No impact — Router-IDs only need to be unique within an area"],answerKey:"A",explanation:"If two routers in DIFFERENT OSPF areas have the same Router-ID AND one is an ASBR, the Type-5 AS External LSAs generated by the ASBR will conflict with Router-LSAs (Type-1) that also carry the same Router-ID. Since Type-5 LSAs are flooded throughout the domain, the conflict causes LSA oscillation (flapping) as routers continuously receive conflicting LSAs from different sources with the same Router-ID. Router-IDs must be unique across the ENTIRE OSPF domain, not just within an area."},
  {id:48,type:"single",topic:"BGP",question:"In BGP, which of the following describes the correct behavior regarding the BGP NOTIFICATION message?",options:["A. NOTIFICATION is used to request peers to resend routing information after a policy change","B. NOTIFICATION reports errors and terminates the BGP session","C. NOTIFICATION is sent periodically to keep the session alive","D. NOTIFICATION is equivalent to a KEEPALIVE with error code"],answerKey:"B",explanation:"BGP NOTIFICATION message: Sent when an error is detected (malformed message, unsupported capability, hold timer expired, etc.). Contains: Error Code, Error Sub-Code, and Error Data. After sending NOTIFICATION, the TCP connection is closed and BGP moves to Idle state. It is NOT used to request route refresh (that uses ROUTE-REFRESH messages). It does NOT keep sessions alive (that's KEEPALIVE). It terminates the session — option B is correct."},
  {id:49,type:"single",topic:"WLAN",question:"In a WLAN network, network engineers can assign access users to different VLANs through VLAN Pool, thereby achieving which of the following benefits?",options:["A. Reducing broadcast domains and improving network performance","B. Increasing the physical coverage area of APs","C. Reducing the number of APs required in a network","D. Improving wireless signal strength"],answerKey:"A",explanation:"VLAN Pool in WLAN: Assigns wireless users to different VLANs automatically (round-robin, random, or hash-based assignment). Benefits: Reduces broadcast domain size — instead of all wireless users in one giant VLAN (large broadcast domain), they're spread across multiple smaller VLANs. Improves network performance — smaller broadcast domains mean less broadcast traffic per user. Provides better scalability. IP management improvement — DHCP scopes per VLAN are smaller and more manageable."},
  {id:50,type:"single",topic:"BFD",question:"When a device creates a single-hop BFD session for the first time, which of the following is CORRECT?",options:["A. The session is automatically created without configuration","B. The peer IP must be bound to the corresponding local interface, and cannot be modified after creation","C. Multiple peer IPs can be bound to the same BFD session","D. BFD sessions are dynamic and self-configure based on routing protocols"],answerKey:"B",explanation:"Single-hop BFD static session on Huawei: When creating a static BFD single-hop session: You must bind the peer IP address to the corresponding local interface. The local and remote discriminators must be specified. Once created, the binding (peer IP to interface) cannot be modified without deleting and recreating the session. This is why BFD static sessions require careful initial configuration. Dynamic BFD (triggered by protocols like OSPF or BGP) is different — those are automatically created by the protocol."},
  {id:51,type:"single",topic:"OSPF",question:"In an OSPF network, the enterprise engineer runs the 'ospf 1 router-id 1.1.1.1' command in the system view of the device to configure the OSPF Router-ID. Is this correct?",options:["A. Yes — 'ospf 1 router-id 1.1.1.1' in system view is the correct syntax","B. No — the Router-ID is configured inside OSPF process view with 'router-id 1.1.1.1'","C. No — the Router-ID can only be configured using a loopback interface","D. Yes — but only takes effect after the OSPF process restarts"],answerKey:"B",explanation:"On Huawei routers, OSPF Router-ID configuration: Enter OSPF process view: 'ospf 1' (enters ospf process 1 view). Then configure: 'router-id 1.1.1.1'. You cannot use 'ospf 1 router-id 1.1.1.1' as a single command in system view — that's not valid syntax. Alternatively, you can configure the global system Router-ID with 'router-id 1.1.1.1' in system view, which OSPF will inherit. The statement in the question describes incorrect syntax."},
  {id:52,type:"single",topic:"BGP",question:"In BGP route flap damping, what is the purpose of this feature?",options:["A. To summarize unstable routes into aggregates","B. To suppress frequently flapping routes by penalizing them and withdrawing advertisement until the route stabilizes","C. To redirect flapping routes to a backup path","D. To notify all BGP peers when a route flap is detected"],answerKey:"B",explanation:"BGP Route Flap Damping (RFC 2439): Penalizes routes that frequently go up and down (flap). Each flap adds a penalty value to the route. When penalty exceeds the suppress limit, the route is withdrawn from advertisements (suppressed). Penalty decreases over time (half-life timer). Route is re-advertised when penalty drops below the reuse limit. This prevents network-wide instability from propagating due to a single unstable route. The feature balances stability vs responsiveness."},
  {id:53,type:"single",topic:"OSPF",question:"In an OSPF network diagram with RTA, RTB, RTC, RTD — where RTB, RTC, and RTD are described as ABR routers in addition to the RTA. What is WRONG with this description?",options:["A. RTA being described as non-ABR when connected only to Area 0 is correct","B. All border routers between areas are ABRs by definition","C. An ABR must have at least one interface in Area 0 and one in a non-backbone area","D. If RTD only has interfaces in Area 0, it is not an ABR regardless of diagram labels"],answerKey:"D",explanation:"An ABR (Area Border Router) must have interfaces in AT LEAST TWO different OSPF areas, with one of those areas being Area 0. If a router (like RTD in the scenario) only has interfaces in Area 0 — even if the diagram labels it as ABR — it is technically only a Backbone Router (BR), not an ABR. An ABR by definition connects the backbone to at least one non-backbone area. The description in the PDF question (answer B/Error) suggests the ABR designation is incorrectly applied."},
  {id:54,type:"single",topic:"OSPF",question:"In an OSPF network, which description of virtual links is WRONG?",options:["A. Virtual link configuration is done in the OSPF process area view","B. Virtual links can be configured through stub areas","C. Virtual links follow OSPF inter-area loop prevention rules","D. Virtual links are used when a non-backbone area cannot directly connect to Area 0"],answerKey:"B",explanation:"Virtual link facts: A — Correct: configured in 'ospf → area X' (area view within OSPF process) using 'vlink-peer router-id'. B — WRONG: Virtual links CANNOT traverse stub areas, Totally Stub areas, or NSSA areas — these cannot be transit areas for virtual links. Only STANDARD areas can be transit areas. C — Correct: virtual links still follow inter-area anti-loop rules (all traffic still logically goes through Area 0). D — Correct: virtual links solve disconnected non-backbone areas."},
  {id:55,type:"single",topic:"BGP",question:"In BGP, the number of routes in the BGP routing table is usually relatively large. To reduce the scale of route sending, which approach is CORRECT?",options:["A. Send all BGP routes to every peer without filtering","B. Control advertised routes using route-policy or filter-policy to send only desired routes","C. Compress the routing table using ZIP before sending","D. Use UDP instead of TCP to send more routes faster"],answerKey:"B",explanation:"BGP route advertisement control: The correct approach is to use routing policies (Route-Policy, filter-policy, ACL, prefix-list, community-filter) to control which routes are advertised to which peers. This is fundamental BGP traffic engineering: 'Outbound policies' on the advertising router filter what is sent. 'Inbound policies' on the receiving router filter what is accepted. This allows: Sending only customer routes to peers. Filtering out internal infrastructure prefixes. Implementing prefix limits. BGP never compresses or uses UDP — it's TCP-based incremental."},
  {id:56,type:"single",topic:"VRRP",question:"In a VRRP network, if the user does not configure VRRP monitoring of the uplink port, when the uplink interface or link of the Master device fails, what happens?",options:["A. VRRP immediately detects the failure and switches to Backup","B. Active/standby failover does NOT occur, resulting in a traffic blackhole","C. VRRP switches after 3 advertisement intervals","D. The Backup detects the failure via BFD and takes over"],answerKey:"B",explanation:"Without VRRP uplink monitoring: VRRP only monitors the local VRRP interface (the gateway interface) — not the uplink to the internet. If the uplink fails but the VRRP interface is still up, the Master continues sending VRRP advertisements. The Backup sees the Master as healthy and stays in Backup state. Result: A traffic BLACKHOLE — traffic is forwarded to the Master, but the Master cannot reach the internet via the failed uplink. Solution: Configure VRRP track interface to reduce Master priority when uplink fails, triggering failover."},
  {id:57,type:"single",topic:"OSPF",question:"Which command correctly configures OSPF Router-ID as 1.1.1.1 for OSPF process 1 on a Huawei router (correct syntax)?",options:["A. ospf 1 router-id 1.1.1.1 (in system view)","B. [Router] ospf 1 → [Router-ospf-1] router-id 1.1.1.1","C. [Router] interface loopback 0 → [Router-LoopBack0] ip address 1.1.1.1","D. router ospf 1 → router-id 1.1.1.1 (Cisco-style)"],answerKey:"B",explanation:"Correct Huawei VRP syntax for OSPF Router-ID: Enter OSPF process view: 'ospf 1' (or 'ospf 1 router-id X.X.X.X' directly when starting the process). Inside OSPF process view: 'router-id 1.1.1.1'. So: [Huawei] ospf 1 → [Huawei-ospf-1] router-id 1.1.1.1. Option A is invalid syntax. Option C sets a loopback IP (which becomes Router-ID indirectly but is not the direct command). Option D is Cisco IOS syntax, not Huawei VRP."},
  {id:58,type:"single",topic:"BGP",question:"In BGP, IBGP devices that are non-clients (neither RR nor clients of any RR) must establish which type of relationship among themselves?",options:["A. No relationship needed — RR handles everything","B. Full mesh iBGP connections between all non-clients","C. Only connect to the RR, not to each other","D. Connect in a ring topology for redundancy"],answerKey:"B",explanation:"In an AS using Route Reflectors: Clients — only peer with the RR (no client-to-client direct sessions needed). Non-clients (routers that are neither RR nor clients) — must form a FULL MESH among themselves AND each must peer with the RR. This is because: The RR reflects routes from clients to non-clients and vice versa. But between non-clients, IBGP split-horizon still applies — they cannot re-advertise iBGP routes to each other without a full mesh. So non-clients must peer directly with each other."},
  {id:59,type:"single",topic:"VRRP",question:"Which of the following is CORRECT about configuring VRRP with BFD association for fast failover?",options:["A. When BFD detects a fault, the Backup immediately switches to Master without waiting for the Master_Down timer","B. When BFD detects a fault, the Backup still waits for Master_Down_Timer to expire before taking over","C. BFD and VRRP cannot be used together on the same device","D. BFD association with VRRP reduces the VRRP advertisement interval to 10ms"],answerKey:"A",explanation:"VRRP + BFD association: Without BFD, the Backup must wait for Master_Down_Timer (typically 3 × advertisement interval + skew = ~3 seconds) before taking over. With BFD association: BFD detects link/path failure in milliseconds (configurable: 300ms×3 = 900ms or faster). When BFD detects a fault, it notifies VRRP immediately. The Backup IMMEDIATELY transitions to Master state without waiting for the standard Master_Down_Timer. This significantly reduces failover time from seconds to sub-seconds."},
  {id:60,type:"single",topic:"Multicast",question:"In multicast, RPF checks select routes from the routing table. Which route has the HIGHEST priority in RPF route selection?",options:["A. Unicast routing table entries","B. MBGP (Multiprotocol BGP) routes","C. Multicast static routes","D. OSPF routes for the source address"],answerKey:"C",explanation:"RPF route selection priority on Huawei (highest to lowest): (1) Multicast static routes — highest priority, manually configured for specific multicast source paths. (2) MBGP routes — multiprotocol BGP routes for multicast SAFI. (3) Unicast routing table — fallback when no multicast-specific routes exist. Multicast static routes are preferred because they represent explicit administrator intent for the multicast topology, which may differ from the unicast forwarding path. This allows the multicast tree to use a different path than unicast traffic."},
];

const TC={OSPF:"#00d4ff","IS-IS":"#a78bfa",BGP:"#fbbf24",VRRP:"#34d399",BFD:"#06b6d4",Multicast:"#f472b6",Firewall:"#f87171","STP/RSTP":"#8b5cf6",STP:"#8b5cf6",WLAN:"#fb923c",ACL:"#38bdf8",IPv6:"#60a5fa","Routing Policy":"#4ade80",VPN:"#fb7185",Security:"#f97316",Routing:"#a3e635",Telemetry:"#e879f9",Community:"#fcd34d","PIM-DM":"#f472b6"};

export default function HCIPBatch6(){
  const[cur,setCur]=useState(0);const[ans,setAns]=useState({});const[sub,setSub]=useState({});const[showExp,setShowExp]=useState({});const[drag,setDrag]=useState({});const[dOver,setDOver]=useState(null);const[view,setView]=useState("exam");const[time,setTime]=useState(0);const tRef=useRef(null);const dIdx=useRef(null);
  useEffect(()=>{tRef.current=setInterval(()=>setTime(t=>t+1),1000);return()=>clearInterval(tRef.current);},[]);
  const fmt=s=>`${String(Math.floor(s/60)).padStart(2,"0")}:${String(s%60).padStart(2,"0")}`;
  const q=QUESTIONS[cur];const tc=TC[q.topic]||"#00d4ff";const done=Object.keys(sub).length;
  useEffect(()=>{if(q.type==="ordering"&&!drag[q.id]){setDrag(p=>({...p,[q.id]:[...q.items].sort(()=>Math.random()-0.5).map(i=>i.id)}));};},[q.id]);
  const isOk=id=>{const qd=QUESTIONS.find(x=>x.id===id);if(!qd)return false;if(qd.type==="single")return ans[id]===qd.answerKey;if(qd.type==="truefalse")return ans[id]===qd.answerKey;if(qd.type==="multiple")return(ans[id]||[]).sort().join()===[...qd.answerKey].sort().join();if(qd.type==="ordering")return(drag[id]||qd.items.map(i=>i.id)).join()===qd.correctOrder.join();return false;};
  const submit=()=>{if(sub[q.id])return;if(q.type==="ordering"){setSub(p=>({...p,[q.id]:true}));setShowExp(p=>({...p,[q.id]:true}));return;}const a=ans[q.id];if(!a||(Array.isArray(a)&&!a.length))return;setSub(p=>({...p,[q.id]:true}));setShowExp(p=>({...p,[q.id]:true}));};
  const cls=(letter,qd)=>{if(!sub[qd.id]){const s=qd.type==="multiple"?(ans[qd.id]||[]).includes(letter):ans[qd.id]===letter;return s?"opt sel":"opt";}const c=qd.type==="multiple"?qd.answerKey.includes(letter):qd.answerKey===letter;const s=qd.type==="multiple"?(ans[qd.id]||[]).includes(letter):ans[qd.id]===letter;if(c)return"opt ok";if(s)return"opt bad";return"opt";};
  const oItems=(drag[q.id]||[]).map(id=>q.items?.find(i=>i.id===id)).filter(Boolean);
  if(view==="results"){let s=0;QUESTIONS.forEach(qq=>{if(sub[qq.id]&&isOk(qq.id))s++;});const pct=Math.round(s/QUESTIONS.length*100);const bd={};QUESTIONS.forEach(qq=>{if(!bd[qq.topic])bd[qq.topic]={t:0,c:0};bd[qq.topic].t++;if(sub[qq.id]&&isOk(qq.id))bd[qq.topic].c++;});
    return(<div style={S.wrap}><style>{css}</style><div style={S.rWrap}><div style={S.rHead}><div style={{fontSize:10,color:"#555",letterSpacing:3}}>BATCH 6 COMPLETE · Q301–360</div><div style={{fontSize:66,fontFamily:"monospace",color:pct>=60?"#00d4ff":"#f87171",lineHeight:1.1,marginTop:8}}>{pct}%</div><div style={{color:"#555",fontSize:12,marginTop:6}}>{s}/{QUESTIONS.length} correct · {fmt(time)}</div><div style={{marginTop:10,fontSize:13,color:pct>=80?"#34d399":pct>=60?"#fbbf24":"#f87171"}}>{pct>=80?"🏆 Excellent!":pct>=60?"✅ Passing — keep it up":"📚 One more batch to go!"}</div></div><div style={S.breakdown}><div style={{fontSize:10,color:"#333",letterSpacing:2,marginBottom:12}}>TOPIC BREAKDOWN</div>{Object.entries(bd).map(([topic,d])=>{const p=d.t?Math.round(d.c/d.t*100):0;const color=TC[topic]||"#00d4ff";return(<div key={topic} style={{marginBottom:9}}><div style={{display:"flex",justifyContent:"space-between",fontSize:11,marginBottom:3}}><span style={{color}}>{topic}</span><span style={{color:"#444"}}>{d.c}/{d.t}</span></div><div style={{background:"#0a0a0a",borderRadius:2,height:3}}><div style={{width:`${p}%`,height:"100%",background:color,borderRadius:2}}/></div></div>);})}</div><button style={{...S.btn,width:"100%",marginTop:18}} onClick={()=>{setAns({});setSub({});setShowExp({});setDrag({});setTime(0);setCur(0);setView("exam");tRef.current=setInterval(()=>setTime(t=>t+1),1000);}}>RETRY BATCH 6</button><div style={{textAlign:"center",fontSize:10,color:"#222",marginTop:12}}>🎯 Final stretch — Batch 7 is the last one!</div></div></div>);}
  return(<div style={S.wrap}><style>{css}</style><div style={S.hdr}><div style={{fontSize:10,color:"#00d4ff",letterSpacing:3}}>HCIP-DATACOM · BATCH 6</div><div style={{fontFamily:"monospace",fontSize:12,color:"#444"}}>{fmt(time)}</div></div><div style={{display:"flex",justifyContent:"space-between",padding:"5px 16px",fontSize:10,color:"#444"}}><span>Q{cur+1}/{QUESTIONS.length}</span><span>{done} answered</span></div><div style={{height:2,background:"#0a0a0f",margin:"0 16px",borderRadius:2,position:"relative",overflow:"hidden"}}><div style={{position:"absolute",height:"100%",background:"#181828",width:`${(cur+1)/QUESTIONS.length*100}%`}}/><div style={{position:"absolute",height:"100%",background:"#00d4ff",width:`${done/QUESTIONS.length*100}%`}}/></div><div style={{display:"flex",flexWrap:"wrap",gap:3,padding:"7px 16px"}}>{QUESTIONS.map((qq,i)=>(<div key={qq.id} onClick={()=>setCur(i)} style={{width:7,height:7,borderRadius:"50%",cursor:"pointer",background:i===cur?"#00d4ff":sub[qq.id]?(isOk(qq.id)?"#34d399":"#f87171"):"#111"}}/>))}</div>
  <div style={S.card}><div style={{fontSize:10,color:"#444",letterSpacing:1.5,marginBottom:12}}><span style={{color:tc}}>◆</span> {q.topic}<span style={{marginLeft:10}}>{q.type==="single"&&"Single Choice"}{q.type==="truefalse"&&"True / False"}{q.type==="multiple"&&"Multiple Choice"}{q.type==="ordering"&&"Drag to Order"}</span></div><div style={S.qText}>{q.question}</div>
  {q.type==="single"&&(<div style={{display:"flex",flexDirection:"column",gap:6,marginTop:14}}>{q.options.map(opt=>{const l=opt.split(".")[0].trim();return(<button key={l} className={cls(l,q)} onClick={()=>!sub[q.id]&&setAns(p=>({...p,[q.id]:l}))} style={S.optB}><span style={{minWidth:16,color:"#333",fontWeight:700}}>{l}</span><span>{opt.slice(opt.indexOf(".")+1).trim()}</span></button>);})}</div>)}
  {q.type==="truefalse"&&(<div style={{display:"flex",gap:10,marginTop:16}}>{["True","False"].map(v=>{let c="opt";if(sub[q.id]){if(v===q.answerKey)c="opt ok";else if(ans[q.id]===v)c="opt bad";}else if(ans[q.id]===v)c="opt sel";return(<button key={v} className={c} onClick={()=>!sub[q.id]&&setAns(p=>({...p,[q.id]:v}))} style={{...S.optB,flex:1,justifyContent:"center",fontSize:13,fontWeight:700}}>{v==="True"?"✓  True":"✗  False"}</button>);})}</div>)}
  {q.type==="multiple"&&(<div style={{display:"flex",flexDirection:"column",gap:6,marginTop:14}}>{q.options.map(opt=>{const l=opt.split(".")[0].trim();return(<button key={l} className={cls(l,q)} onClick={()=>{if(sub[q.id])return;const c=ans[q.id]||[];setAns(p=>({...p,[q.id]:c.includes(l)?c.filter(x=>x!==l):[...c,l]}));}} style={S.optB}><span style={{minWidth:16,color:"#333",fontWeight:700}}>{l}</span><span>{opt.slice(opt.indexOf(".")+1).trim()}</span></button>);})}</div>)}
  {q.type==="ordering"&&(<><div style={{fontSize:10,color:"#fbbf24",marginTop:10,marginBottom:7}}>▸ Drag into correct order — top = first</div>{oItems.map((item,idx)=>{const good=sub[q.id]&&q.correctOrder[idx]===item.id;const bad=sub[q.id]&&q.correctOrder[idx]!==item.id;return(<div key={item.id} draggable={!sub[q.id]} onDragStart={()=>{dIdx.current=idx;}} onDragEnter={()=>setDOver(idx)} onDragOver={e=>e.preventDefault()} onDragEnd={()=>{if(dIdx.current!==null&&dOver!==null){const o=[...(drag[q.id]||[])];const[m]=o.splice(dIdx.current,1);o.splice(dOver,0,m);setDrag(p=>({...p,[q.id]:o}));}dIdx.current=null;setDOver(null);}} style={{display:"flex",alignItems:"center",padding:"8px 11px",marginBottom:4,borderRadius:5,border:`1px solid ${good?"#34d399":bad?"#f87171":dOver===idx?"#00d4ff":"#1a1a28"}`,background:good?"rgba(52,211,153,.1)":bad?"rgba(248,113,113,.08)":dOver===idx?"rgba(0,212,255,.06)":"#0c0c18",cursor:sub[q.id]?"default":"grab"}}><span style={{color:"#2a2a3a",fontSize:10,minWidth:16}}>{idx+1}.</span>{!sub[q.id]&&<span style={{color:"#222",marginRight:6,fontSize:10}}>⠿</span>}{good&&<span style={{color:"#34d399",marginRight:5}}>✓</span>}{bad&&<span style={{color:"#f87171",marginRight:5}}>✗</span>}<span style={{fontSize:12,color:"#bbb"}}>{item.text}</span></div>);})}
  {sub[q.id]&&<div style={{marginTop:9,fontSize:10,color:"#444"}}><span style={{color:"#00d4ff"}}>Correct: </span>{q.correctOrder.map((id,i)=>{const item=q.items.find(x=>x.id===id);return<span key={id} style={{color:"#888"}}>{i+1}. {item?.text}{i<q.correctOrder.length-1?" → ":""}</span>;})}</div>}</>)}
  {!sub[q.id]&&<button style={S.sub} onClick={submit}>Submit Answer</button>}
  {sub[q.id]&&(<div style={{...S.res,background:isOk(q.id)?"rgba(52,211,153,.08)":"rgba(248,113,113,.08)",borderColor:isOk(q.id)?"#34d399":"#f87171",color:isOk(q.id)?"#34d399":"#f87171"}}>{isOk(q.id)?"✓ CORRECT":"✗ INCORRECT"}{!isOk(q.id)&&q.type!=="ordering"&&<span style={{color:"#444",fontWeight:400,fontSize:11}}> · Answer: <span style={{color:"#34d399"}}>{Array.isArray(q.answerKey)?q.answerKey.join(", "):q.answerKey}</span></span>}</div>)}
  {showExp[q.id]&&(<div style={S.expBox}><div style={{fontSize:10,color:"#00d4ff",letterSpacing:2,marginBottom:6}}>EXPLANATION</div><div style={{fontSize:12,color:"#888",lineHeight:1.8}}>{q.explanation}</div></div>)}
  </div>
  <div style={S.nav}><button style={{...S.navB,opacity:cur===0?0.3:1}} disabled={cur===0} onClick={()=>setCur(c=>Math.max(0,c-1))}>← PREV</button><span style={{fontSize:10,color:"#333"}}>{cur+1} / {QUESTIONS.length}</span>{cur<QUESTIONS.length-1?<button style={S.navB} onClick={()=>setCur(c=>c+1)}>NEXT →</button>:<button style={{...S.navB,background:"#34d399",color:"#000",fontWeight:700}} onClick={()=>{clearInterval(tRef.current);setView("results");}}>FINISH</button>}</div>
  <div style={{textAlign:"center",fontSize:10,color:"#1a1a1a",paddingBottom:14}}>HCIP-Datacom H12-821 · Batch 6 of 7 · {done} answered · {QUESTIONS.length-done} remaining</div></div>);
}
const S={wrap:{minHeight:"100vh",background:"#07070d",fontFamily:"'JetBrains Mono','Fira Code','Courier New',monospace",color:"#ddd",paddingBottom:40},hdr:{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"12px 16px 10px",borderBottom:"1px solid #0e0e18"},card:{margin:"5px 13px",background:"#0b0b17",border:"1px solid #161626",borderRadius:7,padding:"16px"},qText:{fontSize:13,lineHeight:1.85,color:"#d0d0d0"},optB:{display:"flex",alignItems:"flex-start",gap:9,padding:"9px 12px",borderRadius:5,border:"1px solid #1a1a28",background:"#070710",color:"#bbb",fontSize:12,textAlign:"left",cursor:"pointer",width:"100%",lineHeight:1.5,fontFamily:"inherit"},sub:{marginTop:16,width:"100%",padding:"10px",background:"#00d4ff",color:"#000",border:"none",borderRadius:5,fontSize:11,fontWeight:700,letterSpacing:2,cursor:"pointer",fontFamily:"inherit"},res:{marginTop:12,padding:"8px 12px",borderRadius:5,border:"1px solid",fontSize:12,fontWeight:700,letterSpacing:1},expBox:{marginTop:12,padding:"12px",background:"#07070e",border:"1px solid #111120",borderRadius:5},nav:{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"12px 16px"},navB:{padding:"6px 14px",background:"#0e0e1c",color:"#00d4ff",border:"1px solid #1a1a2a",borderRadius:4,fontSize:10,letterSpacing:1.5,cursor:"pointer",fontFamily:"inherit",fontWeight:700},btn:{padding:"10px",background:"#00d4ff",color:"#000",border:"none",borderRadius:5,fontSize:11,fontWeight:700,letterSpacing:2,cursor:"pointer",fontFamily:"inherit"},rWrap:{maxWidth:460,margin:"0 auto",padding:"32px 16px"},rHead:{textAlign:"center",padding:"26px 16px",background:"#0b0b17",border:"1px solid #161626",borderRadius:7,marginBottom:16},breakdown:{background:"#0b0b17",border:"1px solid #161626",borderRadius:7,padding:"16px"},};
const css=`@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;700&display=swap');*{box-sizing:border-box;}.opt{display:flex;align-items:flex-start;gap:9px;padding:9px 12px;border-radius:5px;border:1px solid #1a1a28;background:#070710;color:#bbb;font-size:12px;text-align:left;cursor:pointer;width:100%;line-height:1.5;font-family:inherit;transition:all .1s;}.opt:hover:not(.ok):not(.bad){border-color:#242438;background:#0d0d20;}.opt.sel{border-color:#00d4ff;background:rgba(0,212,255,.06);color:#e0e0e0;}.opt.ok{border-color:#34d399;background:rgba(52,211,153,.09);color:#6ee7b7;cursor:default;}.opt.bad{border-color:#f87171;background:rgba(248,113,113,.07);color:#fca5a5;cursor:default;}`;

